controller_interface::InterfaceConfiguration MactController::command_interface_configuration() const
{
  controller_interface::InterfaceConfiguration config{controller_interface::interface_configuration_type::INDIVIDUAL, {}};
  for (const auto & joint : joints_) {config.names.push_back(joint + "/effort");}
  return config;
}

controller_interface::InterfaceConfiguration MactController::state_interface_configuration() const
{
  controller_interface::InterfaceConfiguration config{controller_interface::interface_configuration_type::INDIVIDUAL, {}};
  for (const auto & joint : joints_) {config.names.push_back(joint + "/position");}
  for (const auto & joint : joints_) {config.names.push_back(joint + "/velocity");}
  // The measured torque is read only for the prediction-error term of the update law.
  if (use_measured_torque_) {
    for (const auto & joint : joints_) {config.names.push_back(joint + "/effort");}
  }
  return config;
}

