CallbackReturn MactController::on_init()
{
  auto node = get_node();
  // Defaults that do nothing (no adaptation, no filtering); robot-specific values come from the generated YAML.
  declare(node, "joints", std::vector<std::string>(kJointNames.begin(), kJointNames.end()));
  declare_required(node, "k_p", rclcpp::PARAMETER_DOUBLE_ARRAY);
  declare_required(node, "k_v", rclcpp::PARAMETER_DOUBLE_ARRAY);
  declare_required(node, "robot_adds_gravity", rclcpp::PARAMETER_BOOL);
  declare(node, "adaptation.enabled", false);
  declare(node, "adaptation.gamma", 0.0);
  declare(node, "adaptation.torque_source", std::string("measured"));
  declare(node, "adaptation.R_t", std::vector<double>(kNdof, 1.0));
  declare(node, "adaptation.R_p_link", std::vector<double>(kNumNodes, 0.0));
  declare(node, "adaptation.R_p_param", std::vector<double>(10, 0.0));
  declare(node, "filters.dq_cutoff_hz", 0.0);
  declare(node, "filters.ddq_cutoff_hz", 0.0);
  return CallbackReturn::SUCCESS;
}

bool MactController::read_parameters()
{
  auto node = get_node();
  joints_ = node->get_parameter("joints").as_string_array();
  if (static_cast<int>(joints_.size()) != kNdof) {
    RCLCPP_ERROR(node->get_logger(), "'joints' has %zu names, the model has %d joints", joints_.size(), kNdof);
    return false;
  }

  std::vector<double> values;
  if (!get_required(node, "k_p", values) || !to_vector(node, "k_p", values, k_p_)) {return false;}
  if (!get_required(node, "k_v", values) || !to_vector(node, "k_v", values, k_v_)) {return false;}
  if (!get_required(node, "robot_adds_gravity", robot_adds_gravity_)) {return false;}

  adaptation_enabled_default_ = node->get_parameter("adaptation.enabled").as_bool();
  gamma_ = node->get_parameter("adaptation.gamma").as_double();
  const std::string source = node->get_parameter("adaptation.torque_source").as_string();
  if (source != "measured" && source != "commanded") {
    RCLCPP_ERROR(node->get_logger(), "'adaptation.torque_source' must be 'measured' or 'commanded'");
    return false;
  }
  // The prediction-error term is the only user of the measured torque.
  use_measured_torque_ = (source == "measured") && gamma_ > 0.0;
  if (!to_vector(node, "adaptation.R_t", node->get_parameter("adaptation.R_t").as_double_array(), r_t_)) {return false;}

  // R_p = R_p_link[node] * R_p_param[k], par_REG = [m, m c_x, m c_y, m c_z, Ixx, Ixy, Ixz, Iyy, Iyz, Izz] per node.
  const auto r_p_link = node->get_parameter("adaptation.R_p_link").as_double_array();
  const auto r_p_param = node->get_parameter("adaptation.R_p_param").as_double_array();
  if (static_cast<int>(r_p_link.size()) != kNumNodes || r_p_param.size() != 10) {
    RCLCPP_ERROR(node->get_logger(), "'adaptation.R_p_link' needs %d entries and 'adaptation.R_p_param' 10", kNumNodes);
    return false;
  }
  for (int n = 0; n < kNumNodes; ++n) {
    for (int k = 0; k < 10; ++k) {r_p_(10 * n + k) = r_p_link[n] * r_p_param[k];}
  }
  if (gamma_ < 0.0 || (r_p_.array() < 0.0).any() || (r_t_.array() < 0.0).any()) {
    RCLCPP_ERROR(node->get_logger(), "adaptation gains must be non-negative");
    return false;
  }

  dq_cutoff_hz_ = node->get_parameter("filters.dq_cutoff_hz").as_double();
  ddq_cutoff_hz_ = node->get_parameter("filters.ddq_cutoff_hz").as_double();
  return true;
}

Limits MactController::joint_limits()
{
  // The getters return a copy of the robot's parameters; nothing writes them while the controller runs.
  Limits limits;
  limits.q_min = robot_.get_q_min();
  limits.q_max = robot_.get_q_max();
  limits.dq_max = robot_.get_dq_max();
  limits.ddq_max = robot_.get_ddq_max();
  return limits;
}

CallbackReturn MactController::on_configure(const rclcpp_lifecycle::State &)
{
  if (!read_parameters()) {return CallbackReturn::ERROR;}
  auto node = get_node();

  pi_nominal_ = robot_.get_par_REG();

  trajectory_sub_ = node->create_subscription<trajectory_msgs::msg::JointTrajectory>(
    "~/joint_trajectory", rclcpp::SystemDefaultsQoS(),
    [this](const trajectory_msgs::msg::JointTrajectory::SharedPtr msg) {trajectory_callback(msg);});
  adaptation_srv_ = node->create_service<std_srvs::srv::SetBool>(
    "~/set_adaptation",
    [this](const std_srvs::srv::SetBool::Request::SharedPtr request, std_srvs::srv::SetBool::Response::SharedPtr response) {
      adaptation_enabled_.store(request->data);
      response->success = true;
    });

  state_pub_raw_ = node->create_publisher<StateMsg>("~/controller_state", rclcpp::SystemDefaultsQoS());
  state_pub_ = std::make_unique<realtime_tools::RealtimePublisher<StateMsg>>(state_pub_raw_);
  {
    // sized once here, so filling it in the loop does not allocate
    state_pub_->lock();
    auto & m = state_pub_->msg_;
    m.joint_names = joints_;
    for (auto * point : {&m.reference, &m.feedback, &m.error}) {
      point->positions.assign(kNdof, 0.0);
      point->velocities.assign(kNdof, 0.0);
      point->accelerations.assign(kNdof, 0.0);
    }
    m.output.effort.assign(kNdof, 0.0);
    state_pub_->unlock();
  }
  par_pub_raw_ = node->create_publisher<ParMsg>("~/par_REG", rclcpp::SystemDefaultsQoS());
  par_pub_ = std::make_unique<realtime_tools::RealtimePublisher<ParMsg>>(par_pub_raw_);
  par_pub_->lock();
  par_pub_->msg_.data.assign(kNpar, 0.0);
  par_pub_->unlock();

  // The update law trusts the effort state as the full joint torque: say so if it is never updated.
  if (use_measured_torque_) {
    zero_effort_timer_ = node->create_wall_timer(std::chrono::seconds(1), [this]() {warn_zero_effort();});
  }

  RCLCPP_INFO(node->get_logger(), "Configured: %d joints, %d parameters, robot adds gravity: %s, measured torque: %s",
    kNdof, kNpar, robot_adds_gravity_ ? "yes" : "no", use_measured_torque_ ? "yes" : "no");
  return CallbackReturn::SUCCESS;
}

CallbackReturn MactController::on_activate(const rclcpp_lifecycle::State &)
{
  const auto logger = get_node()->get_logger();
  position_.clear(); velocity_.clear(); effort_state_.clear(); effort_.clear();
  if (!controller_interface::get_ordered_interfaces(state_interfaces_, joints_, "position", position_) ||
    !controller_interface::get_ordered_interfaces(state_interfaces_, joints_, "velocity", velocity_) ||
    (use_measured_torque_ && !controller_interface::get_ordered_interfaces(state_interfaces_, joints_, "effort", effort_state_)) ||
    !controller_interface::get_ordered_interfaces(command_interfaces_, joints_, "effort", effort_))
  {
    RCLCPP_ERROR(logger, "Missing state or command interfaces");
    return CallbackReturn::ERROR;
  }

  for (int j = 0; j < kNdof; ++j) {
    if (!read_value(position_[j].get(), q_(j)) || !read_value(velocity_[j].get(), dq_raw_(j))) {
      RCLCPP_ERROR(logger, "Cannot read the state of joint '%s'", joints_[j].c_str());
      return CallbackReturn::ERROR;
    }
  }

  // Start at rest on the measured pose; a trajectory left in the buffer from a previous activation is not resumed.
  reference_ = State{};
  reference_.q = q_;
  active_id_ = trajectory_buffer_.readFromRT()->id;
  following_ = false;
  {
    std::lock_guard<std::mutex> lock(reference_mutex_);
    snapshot_valid_ = false;   // until the loop runs: trajectories are rejected
  }

  dq_ = dq_raw_;
  dq_raw_prev_ = dq_raw_;
  ddq_.setZero();
  tau_measured_.setZero();
  tau_command_.setZero();
  tau_applied_.setZero();
  command_written_ = false;
  gravity_.setZero();
  pi_hat_ = pi_nominal_;
  adaptation_enabled_.store(adaptation_enabled_default_);
  for (int j = 0; j < kNdof; ++j) {
    zero_effort_cycles_[j] = 0;
    zero_effort_[j].store(false);
    zero_effort_warned_[j] = false;
  }
  return CallbackReturn::SUCCESS;
}

CallbackReturn MactController::on_deactivate(const rclcpp_lifecycle::State &)
{
  {
    std::lock_guard<std::mutex> lock(reference_mutex_);
    snapshot_valid_ = false;
  }
  for (auto & command : effort_) {(void)command.get().set_value(0.0);}
  return CallbackReturn::SUCCESS;
}

// ------------------------------------------------------------------ loop --
//
// Sample k: q, dq, tau_measured are read now; the reference is sampled at `time`.
// The update law compares Y(q_k, dq_k, ddq_k) pi_hat with the torque applied over
// [k-1, k]: tau_measured_k, or tau_applied_ written at the end of cycle k-1.
// Nothing here allocates, blocks or logs.

controller_interface::return_type MactController::update(const rclcpp::Time & time, const rclcpp::Duration & period)
{
  const double dt = period.seconds();
  if (dt <= 0.0) {return controller_interface::return_type::OK;}

  // --- read --- //
  // A value that cannot be read this cycle keeps the previous one (the interface counts the failures).
  for (int j = 0; j < kNdof; ++j) {
    read_value(position_[j].get(), q_(j));
    read_value(velocity_[j].get(), dq_raw_(j));
    if (use_measured_torque_) {
      read_value(effort_state_[j].get(), tau_measured_(j));
      // exactly 0 while the previous command was not: probably not updated by the hardware (diagnostics only)
      zero_effort_cycles_[j] = (tau_measured_(j) == 0.0 && tau_command_(j) != 0.0) ? zero_effort_cycles_[j] + 1 : 0;
      if (zero_effort_cycles_[j] == kZeroEffortCycles) {zero_effort_[j].store(true, std::memory_order_relaxed);}
    }
  }

  // --- estimate: dq filtered, ddq from the difference of the raw dq, filtered --- //
  low_pass(dq_, dq_raw_, dq_cutoff_hz_, dt);
  const Vec ddq_raw = (dq_raw_ - dq_raw_prev_) / dt;
  low_pass(ddq_, ddq_raw, ddq_cutoff_hz_, dt);
  dq_raw_prev_ = dq_raw_;

  // --- limits: parameters of the robot class, read here because they can be changed --- //
  const Limits limits = joint_limits();
  const Vec tau_max = robot_.get_tau_max();
  const Vec dtau_max = robot_.get_dtau_max();

  // --- reference --- //
  const Traj & trajectory = *trajectory_buffer_.readFromRT();
  const std::int64_t now_ns = time.nanoseconds();
  if (trajectory.id != active_id_) {           // a new trajectory: start it from the current reference
    active_id_ = trajectory.id;
    trajectory_origin_ns_ = trajectory.stamp_ns != 0 ? trajectory.stamp_ns : now_ns;
    segment_start_ = reference_;
    segment_start_time_ = 1e-9 * static_cast<double>(now_ns - trajectory_origin_ns_);
    following_ = true;
  }
  if (following_) {
    reference_ = sample(trajectory, segment_start_, segment_start_time_,
      1e-9 * static_cast<double>(now_ns - trajectory_origin_ns_));
  }
  reference_.q = reference_.q.cwiseMax(limits.q_min).cwiseMin(limits.q_max);   // last safety, see trajectory_callback
  {
    std::unique_lock<std::mutex> lock(reference_mutex_, std::try_to_lock);
    if (lock.owns_lock()) {
      reference_snapshot_ = reference_;
      snapshot_time_ns_ = now_ns;
      snapshot_valid_ = true;
    }
  }
  const Vec e = reference_.q - q_;
  const Vec e_dot = reference_.dq - dq_;

  // --- model --- //
  robot_.set_q(q_);
  robot_.set_dq(dq_);
  robot_.set_dqr(reference_.dq);
  robot_.set_ddqr(reference_.ddq);
  Yr_ = robot_.get_Yr();

  // --- law --- //
  tau_ = mact_torque<kNdof, kNpar>(Yr_, pi_hat_, e, e_dot, k_p_, k_v_);

  // --- adapt --- //
  if (adaptation_enabled_.load(std::memory_order_relaxed)) {
    VecPar rate = mact_tracking_rate<kNdof, kNpar>(Yr_, e_dot, r_p_);
    // Y is used only by the prediction-error term, which is zero for gamma = 0. With the commanded torque, the term
    // needs the command of the previous cycle: in the first cycle after activation there is none.
    if (gamma_ > 0.0 && (use_measured_torque_ || command_written_)) {
      robot_.set_ddq(ddq_);
      Y_ = robot_.get_Y();
      // Both are the full joint torque, gravity included, as Y pi_hat: the effort state (e.g. FR3 tau_J),
      // or the previous command plus the gravity the robot adds (modelled with the nominal parameters).
      const Vec & tau_previous = use_measured_torque_ ? tau_measured_ : tau_applied_;
      rate += mact_prediction_rate<kNdof, kNpar>(Y_, tau_previous, pi_hat_, gamma_, r_t_, r_p_);
    }
    pi_hat_ += dt * rate;
  }

  // --- write: remove the gravity the robot adds, saturate, limit the rate --- //
  // The robot adds its own G; it is approximated by the model with the nominal parameters,
  // so that the robot applies Yr pi_hat + (G_robot - G_nominal).
  if (robot_adds_gravity_) {
    reg_G_ = robot_.get_reg_G();
    gravity_ = reg_G_ * pi_nominal_;
  }
  const Vec max_step = dtau_max * dt;
  const Vec command = (tau_ - gravity_).cwiseMax(-tau_max).cwiseMin(tau_max);
  tau_command_ += (command - tau_command_).cwiseMax(-max_step).cwiseMin(max_step);
  for (int j = 0; j < kNdof; ++j) {(void)effort_[j].get().set_value(tau_command_(j));}
  tau_applied_ = tau_command_ + gravity_;   // gravity_ is zero when the robot adds none
  command_written_ = true;

  publish(time);
  return controller_interface::return_type::OK;
}

void MactController::warn_zero_effort()
{
  // Timer of the node's executor, not the loop. The configuration is kept as written.
  for (int j = 0; j < kNdof; ++j) {
    if (zero_effort_[j].load(std::memory_order_relaxed) && !zero_effort_warned_[j]) {
      zero_effort_warned_[j] = true;
      RCLCPP_WARN(get_node()->get_logger(),
        "adaptation.torque_source is 'measured', but the effort state of joint '%s' has been exactly 0 for %d cycles "
        "while the command was not: the hardware interface may not update it (e.g. gz_ros2_control 0.7.x on Humble), "
        "and the update law compares the model with a zero torque. Configuration unchanged.",
        joints_[j].c_str(), kZeroEffortCycles);
    }
  }
}

void MactController::publish(const rclcpp::Time & time)
{
  if (state_pub_->trylock()) {
    auto & m = state_pub_->msg_;
    m.header.stamp = time;
    for (int j = 0; j < kNdof; ++j) {
      m.reference.positions[j] = reference_.q(j);
      m.reference.velocities[j] = reference_.dq(j);
      m.reference.accelerations[j] = reference_.ddq(j);
      m.feedback.positions[j] = q_(j);
      m.feedback.velocities[j] = dq_(j);
      m.feedback.accelerations[j] = ddq_(j);
      m.error.positions[j] = reference_.q(j) - q_(j);
      m.error.velocities[j] = reference_.dq(j) - dq_(j);
      m.output.effort[j] = tau_command_(j);
    }
    state_pub_->unlockAndPublish();
  }
  if (par_pub_->trylock()) {
    for (int i = 0; i < kNpar; ++i) {par_pub_->msg_.data[i] = pi_hat_(i);}
    par_pub_->unlockAndPublish();
  }
}

// ------------------------------------------------------------------ reference input (not real-time) --

void MactController::trajectory_callback(const trajectory_msgs::msg::JointTrajectory::SharedPtr msg)
{
  const auto logger = get_node()->get_logger();
  auto reject = [&](const std::string & reason) {
      RCLCPP_WARN(logger, "Trajectory rejected: %s", reason.c_str());
    };

  // The reference and the time of the loop: the stamp is on the controller manager's clock.
  State start;
  std::int64_t now_ns = 0;
  {
    std::lock_guard<std::mutex> lock(reference_mutex_);
    if (!snapshot_valid_) {return reject("the controller is not running");}
    start = reference_snapshot_;
    now_ns = snapshot_time_ns_;
  }

  const int num_points = static_cast<int>(msg->points.size());
  if (num_points < 1 || num_points > kMaxPoints) {
    return reject("it needs 1 to " + std::to_string(kMaxPoints) + " points, it has " + std::to_string(num_points));
  }
  if (static_cast<int>(msg->joint_names.size()) != kNdof) {
    return reject("it must name all " + std::to_string(kNdof) + " joints");
  }
  std::array<int, kNdof> column{};    // column[j]: where joint j of the controller is in the message
  for (int j = 0; j < kNdof; ++j) {
    const auto it = std::find(msg->joint_names.begin(), msg->joint_names.end(), joints_[j]);
    if (it == msg->joint_names.end()) {return reject("joint '" + joints_[j] + "' missing");}
    column[j] = static_cast<int>(it - msg->joint_names.begin());
  }

  double previous_time = 0.0;
  bool velocities_given = false;
  for (int k = 0; k < num_points; ++k) {
    const auto & point = msg->points[k];
    const double t = rclcpp::Duration(point.time_from_start).seconds();
    if (t <= previous_time) {return reject("time_from_start must be positive and increasing");}
    previous_time = t;
    if (static_cast<int>(point.positions.size()) != kNdof ||
      !(point.velocities.empty() || static_cast<int>(point.velocities.size()) == kNdof) ||
      !(point.accelerations.empty() || static_cast<int>(point.accelerations.size()) == kNdof))
    {
      return reject("point " + std::to_string(k) + ": positions are required, velocities and accelerations empty or complete");
    }
    velocities_given = velocities_given || !point.velocities.empty();
    State & waypoint = incoming_.points[k];
    for (int j = 0; j < kNdof; ++j) {
      waypoint.q(j) = point.positions[column[j]];
      waypoint.dq(j) = point.velocities.empty() ? 0.0 : point.velocities[column[j]];
      waypoint.ddq(j) = point.accelerations.empty() ? 0.0 : point.accelerations[column[j]];
    }
    incoming_.times[k] = t;
  }
  incoming_.size = num_points;

  // Times count from header.stamp, or from the cycle that takes the trajectory when it is zero
  // (as joint_trajectory_controller).
  incoming_.stamp_ns = rclcpp::Time(msg->header.stamp).nanoseconds();
  const double start_time = incoming_.stamp_ns == 0 ? 0.0 : 1e-9 * static_cast<double>(now_ns - incoming_.stamp_ns);
  if (start_time >= incoming_.times[num_points - 1]) {
    return reject("it ends in the past (" + std::to_string(start_time - incoming_.times[num_points - 1]) + " s ago)");
  }

  // Positions only: velocities and accelerations of the cubic spline through them (accelerations given without
  // velocities are replaced). Otherwise as given, a missing one is zero.
  if (!velocities_given) {cubic_spline(incoming_, start, start_time);}

  // Checked from the last reference and time the loop reported, a few cycles before the loop takes it:
  // the first segment will start a little later and be a little shorter. The loop also clamps q_d to the limits.
  std::string reason;
  if (!within_limits(incoming_, start, start_time, joint_limits(), reason)) {return reject(reason);}

  incoming_.id = ++next_id_;
  trajectory_buffer_.writeFromNonRT(incoming_);
  if (start_time >= incoming_.times[0]) {
    RCLCPP_WARN(logger, "Trajectory accepted, but its first point is %.3f s in the past: the reference jumps onto it",
      start_time - incoming_.times[0]);
  } else {
    RCLCPP_INFO(logger, "Trajectory accepted: %d points, first point in %.3f s, last in %.3f s",
      num_points, incoming_.times[0] - start_time, previous_time - start_time);
  }
}

